import 'package:flutter_test/flutter_test.dart';import 'mocks/mock_auth_repository.dart';
void main(){late MockAuthRepository repository;setUp(()=>repository=MockAuthRepository());test('login réussit',()async{final u=await repository.login(email:'admin@lifetown.com',password:'password');expect(u.email,'admin@lifetown.com');expect(repository.currentUser,isNotNull);});test('login échoue',()async{repository.shouldFail=true;expect(()=>repository.login(email:'bad',password:'bad'),throwsException);});test('logout supprime la session',()async{await repository.login(email:'a',password:'b');await repository.logout();expect(repository.currentUser,isNull);});test('refresh retourne un nouveau token',()async{expect(await repository.refreshToken(),'new-token');});}
